import { describe, expect, it } from 'vitest';
import { resolveSeoMetatags } from './resolveSeoMetatags.js';
const seo = {
    metatags: { tenant: 'Acme', product: 'Docs' },
    paths: [
        { path: 'guides/v2', metatags: { 'doc-version': '2', latest: 'true' } },
        { path: 'guides', metatags: { latest: 'false', should_index: 'true' } },
        { path: 'sdk', metatags: { product: 'SDK' } },
    ],
};
describe('resolveSeoMetatags', () => {
    it('returns site metatags when no path matches', () => {
        expect(resolveSeoMetatags(seo, '/changelog')).toEqual({ tenant: 'Acme', product: 'Docs' });
    });
    it('returns an empty object without seo config', () => {
        expect(resolveSeoMetatags(undefined, '/guides/intro')).toEqual({});
    });
    it('returns site metatags without an href', () => {
        expect(resolveSeoMetatags(seo, undefined)).toEqual({ tenant: 'Acme', product: 'Docs' });
    });
    it('applies a matching folder on top of site metatags', () => {
        expect(resolveSeoMetatags(seo, '/guides/intro')).toEqual({
            tenant: 'Acme',
            product: 'Docs',
            latest: 'false',
            should_index: 'true',
        });
    });
    it('lets the longest path win regardless of declaration order', () => {
        expect(resolveSeoMetatags(seo, '/guides/v2/install')).toEqual({
            tenant: 'Acme',
            product: 'Docs',
            'doc-version': '2',
            latest: 'true',
            should_index: 'true',
        });
    });
    it('lets a folder override a site metatag', () => {
        expect(resolveSeoMetatags(seo, 'sdk/node')).toEqual({ tenant: 'Acme', product: 'SDK' });
    });
    it('only matches on whole path segments', () => {
        expect(resolveSeoMetatags(seo, '/guides/v20/install')).toEqual({
            tenant: 'Acme',
            product: 'Docs',
            latest: 'false',
            should_index: 'true',
        });
        expect(resolveSeoMetatags(seo, '/sdk-legacy/node')).toEqual({
            tenant: 'Acme',
            product: 'Docs',
        });
    });
    it('matches a page whose href equals the path', () => {
        expect(resolveSeoMetatags(seo, '/sdk')).toEqual({ tenant: 'Acme', product: 'SDK' });
    });
    it.each([
        ['a query string', '/sdk?ref=nav'],
        ['a fragment', '/sdk#overview'],
        ['a query string and fragment', '/sdk?ref=nav#overview'],
        ['a trailing slash', '/sdk/'],
    ])('matches a folder href with %s', (_label, href) => {
        expect(resolveSeoMetatags(seo, href)).toEqual({ tenant: 'Acme', product: 'SDK' });
    });
    it('matches a nested page whose href carries a query string or fragment', () => {
        expect(resolveSeoMetatags(seo, '/sdk/node?ref=nav#install')).toEqual({
            tenant: 'Acme',
            product: 'SDK',
        });
    });
    it('does not match a different folder that shares a prefix', () => {
        expect(resolveSeoMetatags(seo, '/sdk-legacy?ref=nav')).toEqual({
            tenant: 'Acme',
            product: 'Docs',
        });
    });
    it('does not mutate the config', () => {
        const before = JSON.stringify(seo);
        resolveSeoMetatags(seo, '/guides/v2/install');
        expect(JSON.stringify(seo)).toBe(before);
    });
});
